n="<?php echo esc_url( $post_url ); ?>"><input type="hidden" name="action" value="fixreport_checklist_template"><input type="hidden" name="checklist_operation" value="delete"><input type="hidden" name="checklist_id" value="<?php echo esc_attr( $key ); ?>"><input type="hidden" name="checklist_revision" value="<?php echo esc_attr( $template['revision'] ); ?>"><?php wp_nonce_field( 'fixreport_checklist_delete_' . $key, 'checklist_nonce' ); ?><label><input type="checkbox" name="checklist_confirm" value="yes" required> <?php esc_html_e( 'Confirm retiring this task', 'fixreport-maintenance-logger' ); ?></label> <button class="button button-link-delete" type="submit"><?php esc_html_e( 'Retire task', 'fixreport-maintenance-logger' ); ?></button></form>
