	<h3><?php esc_html_e( 'Status history', 'fixreport-maintenance-logger' ); ?></h3><?php if ( ! $history ) : ?><p><?php esc_html_e( 'No status changes recorded.', 'fixreport-maintenance-logger' ); ?></p><?php else : ?><ol class="frc-history"><?php foreach ( $history as $event ) : ?><li><strong><?php echo esc_html( 'completed' === $event['event_type'] ? __( 'Completed', 'fixreport-maintenance-logger' ) : __( 'Reopened', 'fixreport-maintenance-logger' ) ); ?></strong><span><?php echo esc_html( FixReport_Checklist_Admin::display_time( $event['occurred_at_utc'] ) . ' · ' . FixReport_Checklist_Events::actor_label( $event ) ); ?></span><p><?php echo esc_html( $event['title_snapshot'] ); ?><?php if ( $event['category_key_snapshot'] ) : ?> · <?php echo esc_html( isset( $labels[ $event['category_key_snapshot'] ] ) ? $labels[ $event['category_key_snapshot'] ] : $event['category_key_snapshot'] ); ?><?php endif; ?></p><?php if ( $event['description_snapshot'] ) : ?><p><?php echo esc_html( $event['description_snapshot'] ); ?></p><?php endif; ?><?php if ( $event['note'] ) : ?><blockquote><?php echo esc_html( $event['note'] ); ?></blockquote><?php endif; ?></li><?php endforeach; ?></ol><?php if ( $history_next ) : ?><a class="button" href="<?php echo esc_url( add_query_arg( array( 'task' => $key, 'history_before' => $history_next ), $page_url ) ); ?>"><?php esc_html_e( 'Older history', 'fixreport-maintenance-logger' ); ?></a><?php endif; ?><?php endif; ?></dialog><?php endif; ?>
